server.createContext("/resources", exchange -> {
    if (exchange.getRequestMethod().equals("POST")) {
        respond(exchange, 201, "{\"id\":5}"); // UTWORZONO nowy zasob
    }
});
server.createContext("/resources/1", exchange -> {
    String method = exchange.getRequestMethod();
    if (method.equals("GET")) respond(exchange, 200, "{\"id\":1}"); // ODCZYT istniejacego
    if (method.equals("DELETE")) { exchange.sendResponseHeaders(204, -1); } // sukces, brak tresci
});

server.createContext("/resources/999999", exchange -> respond(exchange, 404, "{\"error\":\"Nie znaleziono\"}"));

server.createContext("/admin/reports", exchange -> {
    boolean loggedIn = hasValidToken(exchange);
    boolean isAdmin = loggedIn && hasAdminRole(exchange);
    if (!loggedIn) { respond(exchange, 401, "{\"error\":\"Wymagane logowanie\"}"); return; }
    if (!isAdmin) { respond(exchange, 403, "{\"error\":\"Brak uprawnien\"}"); return; }
    respond(exchange, 200, "{\"report\":\"...\"}");
});

